def find_smallest_even_node(arr):
    even_nodes = []

    for i in range(len(arr)):
        if arr[i] % 2 == 0:
            even_nodes.append((arr[i], i))

    if not even_nodes:
        return []

    smallest_value = min(even_nodes, key=lambda x: x[0])[0]
    smallest_nodes = [node for node in even_nodes if node[0] == smallest_value]

    return min(smallest_nodes, key=lambda x: x[1])

# Test cases
